function predictWithBrowserModel(features360) {
    if (!GLOVE_MODEL || !features360 || features360.length !== 360) {
        return { prediction: '—', confidence: 0 };
    }
    const nClasses = GLOVE_MODEL.n_classes;
    const votes = new Array(nClasses).fill(0);

    for (const tree of GLOVE_MODEL.forest) {
        let nodeIdx = 0;
        while (nodeIdx >= 0) {
            const node = tree[nodeIdx];
            if (node.f === -2) { // leaf node
                // Add probability distribution from this leaf
                const sum = node.v.reduce((a, b) => a + b, 0);
                if (sum > 0) {
                    for (let c = 0; c < nClasses; c++) {
                        votes[c] += node.v[c] / sum;
                    }
                }
                break;
            }
            if (features360[node.f] <= node.th) {
                nodeIdx = node.l;
            } else {
                nodeIdx = node.r;
            }
        }
    }

    const totalVotes = GLOVE_MODEL.forest.length;
    let maxIdx = 0;
    let maxVal = -1;
    for (let c = 0; c < nClasses; c++) {
        const prob = votes[c] / totalVotes;
        if (prob > maxVal) {
            maxVal = prob;
            maxIdx = c;
        }
    }

    const confidence = Math.round(maxVal * 100);
    const prediction = GLOVE_MODEL.classes[maxIdx];
    return {
        prediction: confidence >= 40 ? prediction : '—',
        confidence: confidence
    };
}
